import { useState, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api"; // your axios instance
import { AuthContext } from "../contexts/AuthContext";

export default function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [otp, setOtp] = useState("");
  const [requireOtp, setRequireOtp] = useState(false);
  const [tempToken, setTempToken] = useState(null);
  const [tempUser, setTempUser] = useState(null);
  const [error, setError] = useState("");

  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    try {
      if (!requireOtp) {
        // Step 1: email + password login
        const res = await api.post("/auth/login", { email, password });
        const data = res.data;

        if (data.requireTotp) {
          // Student needs OTP
          setRequireOtp(true);
          setTempToken(data.token);
          setTempUser(data.user);
          return;
        }

        // Admin/Comelec: login immediately
        login({ token: data.token, user: data.user });
        if (data.user.role === "admin") navigate("/admin-dashboard");
        else if (data.user.role === "comelec") navigate("/comelec-dashboard");
        else navigate("/"); // fallback
      } else {
        // Step 2: verify OTP
        const res = await api.post("/auth/totp/verify-login", {
          token: tempToken,
          otp,
        });

        login({ token: res.data.token, user: res.data.user });
        navigate("/"); // redirect after OTP success
      }
    } catch (err) {
      console.error(err);
      setError(err.response?.data?.error || "Login failed");
    }
  };

  return (
    <div style={{ maxWidth: "400px", margin: "50px auto", fontFamily: "Arial, sans-serif" }}>
      <h2 style={{ textAlign: "center", marginBottom: "20px" }}>Login</h2>

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {!requireOtp && (
          <>
            <input
              type="email"
              placeholder="Email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc" }}
            />
            <input
              type="password"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc" }}
            />
          </>
        )}

        {requireOtp && (
          <>
            <p style={{ textAlign: "center", color: "#555" }}>
              Enter the 6-digit OTP from your authenticator app
            </p>
            <input
              type="text"
              placeholder="6-digit OTP"
              value={otp}
              onChange={(e) => setOtp(e.target.value)}
              required
              style={{
                padding: "10px",
                borderRadius: "5px",
                border: "1px solid #ccc",
                textAlign: "center",
                letterSpacing: "3px",
              }}
            />
          </>
        )}

        <button
          type="submit"
          style={{
            padding: "12px",
            borderRadius: "5px",
            border: "none",
            backgroundColor: "#007bff",
            color: "#fff",
            fontWeight: "bold",
            cursor: "pointer",
          }}
        >
          {requireOtp ? "Verify OTP" : "Login"}
        </button>
      </form>

      {error && <p style={{ marginTop: "20px", color: "red", textAlign: "center" }}>{error}</p>}
    </div>
  );
}
